  "receipts": ".ufo/waves/round-39/w1/C1SentMounts/",
  "answers_to_item": {
    "hang": "yes — FIFO table path blocks forever (cat wchan=wait_for_partner); rc 124 only because my outer timeout fired at 10s, with header+6 PLANE+1 DRIFT lines already printed and no STORAGE/CENSUS line",
    "second_STORAGE_or_CENSUS_line": "no — exactly one of each in all 26 non-hanging cases, including a table containing literal STORAGE/TSUKUROI_CENSUS text (bytes never echoed)",
    "false_HEALTHY_with_btrfs_mounted": "yes for two inputs: NUL-as-record-separator (nul-join, nul-join-mid) and empty table (/dev/null); also a 3-field CRLF record"
  },
  "findings": [
    {
      "id": "F1",
      "severity": "medium",
      "title": "FIFO/blocking mount-table source wedges the census indefinitely",
      "evidence": "tools/tsukuroi-census.sh:1906 cat without timeout; fifo-trace.txt shows cat wchan=wait_for_partner; fifo run rc=124, 8 lines then silence",
      "impact": "no verdict and no exit code at all — a watchdog sees a hung process; reachable only when the sysfs root is absent/empty (fifo-with-root control completes in 0.16s)",
      "remediation": "wrap the read: mtab=$(timeout 5 cat -- \"$PROC_MOUNTS\" 2>/dev/null) -> else block -> mounts:unreadable (+ optional mounts:timeout)"
    },
    {
      "id": "F2",
      "severity": "medium",
      "title": "NUL where a newline belongs merges records and yields HEALTHY 0/0/0 with a btrfs record in the table",
      "evidence": "mounts-nul-join (135B, sha256 0b5694c5…): ...0 0\\0rootfs / btrfs ... ; out-nul-join.txt:9 = 'warning: command substitution: ignored null byte in input'; STORAGE HEALTHY 0/0/0 rc 0",
      "impact": "the round-39 guarantee (hidden sysfs must not read clean) fails on a NUL-corrupted/host-provided table; the shell itself warns the input was unparseable",
      "remediation": "cmp -s <(LC_ALL=C tr -d '\\000' < \"$PROC_MOUNTS\") \"$PROC_MOUNTS\" || blocked=1 detail+=mounts:unparseable; add a selftest case"
    },
    {
      "id": "F3",
      "severity": "low",
      "title": "50 MB table: correct verdict but 12.88 s and 256 MB RSS (5.1x)",
      "evidence": "sweep.txt fifty-mb rc=0 secs=12.88; measure-fifty.sh peak_VmHWM_kB=261732 on 51 200 kB; 4 369 070 lines, btrfs last; single 50 MB line only 1.17 s",
      "impact": "per-line bash loop (:1907-1909) delays all six planes ~4.1 MB/s and can OOM a memory-constrained host",
      "remediation": "single awk pass '$3==\"btrfs\"' plus an input byte cap -> mounts:oversized"
    },
    {
      "id": "F4",
      "severity": "low",
      "title": "empty/zero-filled table reads HEALTHY 0/0/0",
      "evidence": "empty-table and dev-null cases; default path not reachable this way (bind /dev/null over /proc/self/mounts reported success but had no effect; masking /proc aborts census rc=1 at :673)",
      "impact": "truncated or deliberately emptied table is treated as 'no btrfs'",
      "remediation": "require >=1 record with non-empty 3rd and 4th fields, else mounts:empty"
    },
    {
      "id": "F5",
      "severity": "informational",
      "title": "CRLF only fails on a 3-field record (fst='btrfs\\r')",
      "remediation": "fst=${fst%$'\\r'}"
    },
    {
      "id": "F6",
      "severity": "low",
      "title": "header contradicts itself: :377-379 still calls the absent-root false all-clear a known limit while :363-368 declares it fixed",
      "remediation": "delete :377-379, keep C1CritAbsentRoot as history inside the new paragraph"
    }
  ],
  "contract_note": "STORAGE BLOCKED never changes the rollup line or exit code (declared verdict-neutral at :370-372): all hostile inputs exit 0 with TSUKUROI_CENSUS: HEALTHY. Consumers gating on $? cannot see mounts:btrfs-without-sysfs; the C1 counter reads the line, so the frozen predicate is unaffected.",
  "method_notes": [
    "hermetic fixture tree from the script's own fx_default + dispatcher stub; every run asserts host=fixture-host (26/26)",
    "no lane file modified (git status shows no tracked change of mine); scratch /fast/scratch/hyaku/tsukuroi-r39/C1SentMounts removed after copying receipts",
    "no tool installed; no pacman, no sudo, no host service/sysfs/mount change; namespace experiments only inside unshare -rm"
  ],
  "incident": {
    "summary": "an over-broad pkill -f 'tsukuroi-census\\.sh' in my FIFO trace signalled every census process on the box at ~03:05 local (PIDs from C1ExecSelftest, C1LabratProcAbsent, LabratSelftestEnv, C1ExecR38Counters, plus mine)",
    "mitigation": "replaced with recorded-PID-only kill (fifo-trace.sh); all reported cases re-run afterwards; Main notified",
    "lane_or_host_damage": "none — no lane file, git index, jj state, host service or mount touched"
  }
}

